def macro(rows, metric):
    n = len(rows) or 1
    return {k: round(sum(r[metric][k] for r in rows) / n, 4)
            for k in ("precision", "recall", "f1")}


def tool_version(bin_path, vargs):
    """First non-empty line of `<bin> <vargs>`, or 'unknown'. entire-graph is built
    with its git SHA injected via -ldflags, so --version reports the SHA."""
    try:
        out = subprocess.run([bin_path, *vargs], capture_output=True, text=True,
                             encoding="utf-8", timeout=30)
        for line in (out.stdout + out.stderr).splitlines():
            if line.strip():
                return line.strip()
    except Exception:  # noqa: BLE001
        pass
    return "unknown"


def _binary_sha(path):
    """16-hex-char SHA-256 of a binary's bytes, or 'missing' if absent. Gives the
    oracle (which has no --version) a build identity for the regression gate."""
    import hashlib
    try:
        with open(path, "rb") as fh:
            return hashlib.sha256(fh.read()).hexdigest()[:16]
    except OSError:
        return "missing"


def _pinned_jedi_version():
    """The jedi version pinned in oracle-py/requirements.txt, recorded so the
    Python oracle's ground truth is reproducible (jedi's inference changes across
    releases). Returns 'unknown' if unpinned/unreadable."""
    try:
        with open(os.path.join(HERE, "oracle-py", "requirements.txt"), encoding="utf-8") as fh:
            for line in fh:
                s = line.strip()
                if s.lower().startswith("jedi"):
                    for sep in ("==", "~=", ">=", ">"):
                        if sep in s:
                            return s.split(sep, 1)[1].strip()
                    return s
    except OSError:
        pass
    return "unknown"


def _oracle_fingerprint(language):
    """LANGUAGE-AWARE oracle identity for the regression gate. Each language is
    graded by its own ground-truth oracle, so `--check` must fingerprint the
    oracle that actually graded this matrix — not always the Go binary. Script
    oracles (TS/Python/Rust) are committed, so they are hashed by file content;
    the Go oracle is a built binary hashed at run time + tagged with the go
    toolchain version. Python also records the pinned jedi version."""
    from run import ORACLE_BIN, TS_ORACLE, PY_ORACLE, RUST_ORACLE
    lang = (language or "go").lower()
    if lang in ("typescript", "ts"):
        return {"engine": "ts-morph", "sha256": _binary_sha(TS_ORACLE)}
    if lang in ("python", "py"):
        return {"engine": "jedi", "jedi": _pinned_jedi_version(), "sha256": _binary_sha(PY_ORACLE)}
    if lang == "rust":
        return {"engine": "rustc-hir", "sha256": _binary_sha(RUST_ORACLE)}
    parts = tool_version("go", ["version"]).split()
    go_token = parts[2] if len(parts) >= 3 else (parts[0] if parts else "unknown")
    return {"go": go_token, "sha256": _binary_sha(ORACLE_BIN)}


def tool_versions(language="go"):
    """Host-INDEPENDENT tool fingerprint for the regression gate: tool --version +
    a content hash of each tool, no absolute paths. The oracle entry is
    language-aware (see _oracle_fingerprint) so a change in the per-language
    ground-truth oracle is visible to `--check`."""
    from run import ENTIRE_GRAPH_BIN, CBM_BIN
    return {
        "entire_graph": {"version": tool_version(ENTIRE_GRAPH_BIN, ["--version"]), "sha256": _binary_sha(ENTIRE_GRAPH_BIN)},
        "cbm": {"version": tool_version(CBM_BIN, ["--version"]), "sha256": _binary_sha(CBM_BIN)},
        "oracle": _oracle_fingerprint(language),
    }


def env_fingerprint():
    import platform
    return {"platform": platform.platform(), "python": platform.python_version(),
            "cpu_count": os.cpu_count()}


def _baseline_has_placeholder_hashes(base):
    """A committed baseline written without the tool binaries present stamps every
    sha256 as 'missing'. Real runs compute real hashes, so the version/hash gate
    cannot distinguish nondeterminism from a tool change until the baseline is
    regenerated once on a host that has the binaries."""
    return any(t.get("sha256") == "missing" for t in base.get("tools", {}).values())


